/**
 * Provenance types.
 *
 * Every statistic the platform shows carries a `dataSourceId`. That is what lets
 * the UI render "Source: CMHC · Updated Oct. 2026" — or, right now, an unambiguous
 * "Demo data · Not live market data" badge. A statistic with no traceable source
 * should never reach the screen.
 */

export type DataSourceType =
  /** Synthetic values generated by this repository for demonstration. */
  | "demo"
  /** Municipal or provincial open data portals. */
  | "open-data"
  /** Federal agencies (CMHC, Statistics Canada). */
  | "government"
  /** Commercial feeds that require a licence agreement. */
  | "licensed"
  /** Hand-entered by an operator. */
  | "manual"
  /** Computed by this application from one or more other sources. */
  | "derived";

export type DataSourceStatus =
  /** Connected and importing on schedule. */
  | "active"
  /** Identified as a future integration, not yet connected. */
  | "planned"
  /** Connected but the last successful import is older than its refresh interval. */
  | "stale"
  /** The last import run failed. */
  | "error";

export interface DataSource {
  id: string;
  name: string;
  sourceType: DataSourceType;
  /** Where the data comes from, or documentation for it. */
  url: string;
  /** ISO timestamp of the last successful refresh, or null if never imported. */
  lastUpdated: string | null;
  status: DataSourceStatus;
  /** Licence or terms of use that govern redistribution. */
  licence: string | null;
  description: string;
  /** How often the upstream publisher releases new data. */
  refreshCadence: "monthly" | "quarterly" | "annual" | "daily" | "irregular";
}

/**
 * The provenance of one displayed statistic, denormalised for the UI.
 * `isDemo` is what the source badge keys off — it is not cosmetic.
 */
export interface Attribution {
  sourceId: string;
  sourceName: string;
  /** ISO timestamp shown as "Updated Jun. 2026". */
  updatedAt: string | null;
  isDemo: boolean;
}

export type ImportRunStatus = "running" | "success" | "failed" | "partial";

/** One execution of an import job — the audit trail for automated pipelines. */
export interface ImportRun {
  id: string;
  dataSourceId: string;
  startedAt: string;
  completedAt: string | null;
  status: ImportRunStatus;
  recordsImported: number;
  errorMessage: string | null;
  /** What kicked the run off, useful when both cron and manual triggers exist. */
  triggeredBy: "schedule" | "manual" | "webhook";
}
